def busqueda_binaria(lista, objetivo):
    inicio = 0
    fin = len(lista) - 1
    while inicio <= fin:
        medio = (inicio + fin) // 2
        if lista[medio] == objetivo:
            return medio
        elif lista[medio] < objetivo:
            inicio = medio + 1
        else:
            fin = medio - 1
    return -1

def es_palindromo(texto):
    limpio = texto.lower().replace(' ', '')
    izquierda = 0
    derecha = len(limpio) - 1
    while izquierda < derecha:
        if limpio[izquierda] != limpio[derecha]:
            return False
        izquierda += 1
        derecha -= 1
    return True

def ordenar_burbuja(numeros):
    datos = numeros[:]
    n = len(datos)
    for i in range(n):
        for j in range(n - 1 - i):
            if datos[j] > datos[j + 1]:
                datos[j], datos[j + 1] = datos[j + 1], datos[j]
    return datos

def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def maximo(numeros):
    mayor = numeros[0]
    for x in numeros[1:]:
        if x > mayor:
            mayor = x
    return mayor

def tabla_multiplicar(n):
    tabla = []
    for i in range(1, n + 1):
        fila = []
        for j in range(1, n + 1):
            fila.append(i * j)
        tabla.append(fila)
    return tabla

def promedios(notas_por_estudiante):
    resultado = {}
    for nombre, notas in notas_por_estudiante.items():
        if notas:
            resultado[nombre] = sum(notas) / len(notas)
        else:
            resultado[nombre] = 0
    return resultado

def palabras_largas(texto, minimo):
    cuenta = 0
    for palabra in texto.split():
        if len(palabra) >= minimo:
            cuenta += 1
    return cuenta
